// Typed access to weapons.json: one-hand weapons, off-hands and staves a warlock can use, in level then item-level order.
// Regenerated by tools/weapons/gen.py from the game client and classic server data; the pages read everything from it.
import raw from './weapons.json';
import type { Side, Source } from './gear';

export type Slot = 'main' | 'off' | 'staff';
export type StatKey = 'sp' | 'shadow' | 'fire' | 'int' | 'sta' | 'spi' | 'mp5' | 'crit' | 'hit' | 'haste';
export interface Weapon {
  id: number;
  name: string;
  quality: 1 | 2 | 3 | 4 | 5;
  ilvl: number;
  req: number | null;
  /** where `req` came from when the item has no level requirement: its quest's level, or an estimate from item level */
  reqFrom?: 'quest' | 'ilvl';
  slot: Slot;
  type: string;                  // Dagger, Sword, Held in off-hand, Staff
  side: Side | null;
  stats: Partial<Record<StatKey, number>>;
  affixes?: boolean;             // <Random enchantment>: rolls a suffix, so its listed stats are only the base
  source: Source | null;
}
export interface WeaponData { build: string; pulled: string; sourceNote: string; items: Weapon[]; noSource: Weapon[] }
export const data = raw as WeaponData;

/** spell damage, shown up front on each row: [key, short label, full name] */
export const POWER: [StatKey, string, string][] = [['sp', 'SP', 'Spell Power'], ['shadow', 'ShP', 'Shadow spell damage'], ['fire', 'FP', 'Fire spell damage']];
/** the other stats → short label, in the order rows show them */
export const STAT_LABEL: [StatKey, string][] = [
  ['int', 'Int'], ['sta', 'Sta'], ['spi', 'Spi'], ['mp5', 'MP5'], ['crit', 'Crit'], ['hit', 'Hit'], ['haste', 'Haste'],
];
export const statLine = (w: Weapon) => STAT_LABEL.filter(([k]) => w.stats[k]).map(([k, l]) => `${w.stats[k]} ${l}`).join(' · ');
export const powerOf = (w: Weapon) => POWER.filter(([k]) => w.stats[k]).map(([k, label, full]) => ({ key: k, label, full, value: w.stats[k]! }));
